def lookup(queues, filter_by=None):
    if filter_by is None:
        return queues  # Return all queues if no filter criteria is specified

    filtered_queues = []
    for queue in queues:
        if all(getattr(queue, attr, None) == value for attr, value in filter_by.items()):
            filtered_queues.append(queue)

    return filtered_queues

