from typing import List

def build_order(commands: List[str]) -> List[str]:
    graph = {}
    for command in commands:
        target, *dependencies = command.replace(':', '').split()[1:]
        graph[target] = dependencies

    visited = set()
    result = []

    def dfs(node):
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in result and not dfs(neighbor):
                return False
        result.append(node)
        visited.remove(node)
        return True

    for node in graph:
        if not dfs(node):
            return []

    return result

