import time
from functools import wraps

class CooldownError(Exception):
    def __init__(self, remaining_time):
        self.remaining_time = remaining_time

def cooldown(duration, bucket_type):
    cooldowns = {}

    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            key = (func.__name__, bucket_type)
            current_time = time.time()

            if key in cooldowns:
                cooldown_end = cooldowns[key]
                remaining_time = max(0, cooldown_end - current_time)
                if remaining_time > 0:
                    raise CooldownError(remaining_time)
            cooldowns[key] = current_time + duration
            return await func(*args, **kwargs)
        return wrapper
    return decorator

