    def __init__(self):
        self.top = None
        self.size = 0

    def apilar(self, elemento):
        nuevo_nodo = Nodo(elemento, self.top)
        self.top = nuevo_nodo
        self.size += 1

    def desapilar(self):
        if self.top is None:
            return None
        elemento = self.top.elemento
        self.top = self.top.siguiente
        self.size -= 1
        return elemento

    def es_vacia(self):
        return self.top is None

    def tamano(self):
        return self.size

    def invertir(self):
        auxiliar = Pila()
        nodo_auxiliar = self.top
        for i in range(self.size):
            auxiliar.apilar(nodo_auxiliar.elemento)
            nodo_auxiliar = nodo_auxiliar.siguiente
        return auxiliar

    def copiar(self):
        return self.invertir().invertir()

    def __repr__(self):
        resultado = []
        auxiliar = self
        while not auxiliar.es_vacia():
            resultado.append(str(auxiliar.desapilar()))
        return ' '.join(resultado)

def count_comment_words(input_str: str) -> dict:
