import subprocess

class CommandManager:
    def __init__(self, command, params, output_path=None, stdout_type='text'):
        self.command = command
        self.name = self.command
        self.params = params
        self.output_path = output_path
        self.stdout_type = stdout_type
        self.process = None

    def start(self):
        if self.process is not None and self.process.poll() is None:
            raise RuntimeError("A command is already running")

        if self.stdout_type == 'text':
            stdout_arg = subprocess.PIPE
        elif self.stdout_type == 'file':
            stdout_arg = open(self.output_path, 'w')
        else:
            raise ValueError("Invalid stdout_type")

        self.process = subprocess.Popen([self.command] + self.params, stdout=stdout_arg)

    def stop(self):
        if self.process is not None and self.process.poll() is None:
            self.process.terminate()
            self.process = None

    def get_output(self):
        if self.stdout_type == 'text':
            if self.process is not None and self.process.poll() is None:
                return self.process.communicate()[0].decode('utf-8')
            else:
                raise RuntimeError("No running command to get output from")
        elif self.stdout_type == 'file':
            raise NotImplementedError("Retrieving output from file not supported")
        else:
            raise ValueError("Invalid stdout_type")

