import random

def partition(arr, low, high):
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

def quickselect(arr, low, high, i):
    if low < high:
        pivot_index = partition(arr, low, high)
        if pivot_index == i - 1:
            return arr[pivot_index]
        elif pivot_index > i - 1:
            return quickselect(arr, low, pivot_index - 1, i)
        else:
            return quickselect(arr, pivot_index + 1, high, i)
    return arr[low]

def find_order_statistic(arr, i):
    if i < 1 or i > len(arr):
        return None  # Invalid input
    random.shuffle(arr)  # Shuffle the array to ensure expected O(n) time
    return quickselect(arr, 0, len(arr) - 1, i)

