def request_json(path: str, params: dict, expect_errors: bool, headers: dict, extra_environ: dict, status: int) -> dict:
    try:
        response = requests.post(path, json=params, headers=headers, environ=extra_environ)
        response.raise_for_status()  # Raise an HTTPError if the HTTP request returned an unsuccessful status code
        if expect_errors and response.status_code == status:
            return response.json()
        elif not expect_errors and response.status_code == status:
            return response.json()
        else:
            raise Exception(f"Unexpected status code: {response.status_code}")
