import os
import shutil

def organize_images(source_dir: str) -> None:
    if not os.path.exists(source_dir):
        print(f"Source directory '{source_dir}' does not exist.")
        return

    if not os.listdir(source_dir):
        print(f"Source directory '{source_dir}' is empty.")
        return

    file_extensions = set()
    for file in os.listdir(source_dir):
        if os.path.isfile(os.path.join(source_dir, file)):
            file_extensions.add(os.path.splitext(file)[1][1:].lower())

    for ext in file_extensions:
        sub_dir = os.path.join(source_dir, ext)
        os.makedirs(sub_dir, exist_ok=True)

    for file in os.listdir(source_dir):
        if os.path.isfile(os.path.join(source_dir, file)):
            ext = os.path.splitext(file)[1][1:].lower()
            src_path = os.path.join(source_dir, file)
            dest_path = os.path.join(source_dir, ext, file)
            shutil.move(src_path, dest_path)

