class CallbackManager:
    def __init__(self):
        self.callbacks = {}

    def register_callback(self, callback_func: callable) -> int:
        callback_id = id(callback_func)
        self.callbacks[callback_id] = callback_func
        return callback_id

    def trigger_callback(self, callback_id: int, *args, **kwargs):
        callback_func = self.callbacks.get(callback_id)
        if callback_func:
            return callback_func(*args, **kwargs)
        else:
            raise ValueError("Callback ID not found")

