def recall(y_true, y_pred, k):
    total_recall = 0
    for query_id in y_true:
        relevant_docs = set(y_true[query_id])
        predicted_docs = y_pred.get(query_id, [])
        predicted_docs = predicted_docs[:k]  # Consider only top k predictions
        true_positives = len(relevant_docs.intersection(predicted_docs))
        total_recall += true_positives / len(relevant_docs) if len(relevant_docs) > 0 else 0
    return total_recall / len(y_true)

def mrr(y_true, y_pred, k):
    total_rr = 0
    for query_id in y_true:
        relevant_docs = set(y_true[query_id])
        predicted_docs = y_pred.get(query_id, [])
        predicted_docs = predicted_docs[:k]  # Consider only top k predictions
        for rank, doc in enumerate(predicted_docs, 1):
            if doc in relevant_docs:
                total_rr += 1 / rank
                break  # Stop at the first relevant document
    return total_rr / len(y_true)

def map_score(y_true, y_pred, k):
    total_map = 0
    for query_id in y_true:
        relevant_docs = set(y_true[query_id])
        predicted_docs = y_pred.get(query_id, [])
        predicted_docs = predicted_docs[:k]  # Consider only top k predictions
        precision_at_k = 0
        num_relevant_at_k = 0
        for i, doc in enumerate(predicted_docs, 1):
            if doc in relevant_docs:
                num_relevant_at_k += 1
                precision_at_k += num_relevant_at_k / i
        if num_relevant_at_k > 0:
            total_map += precision_at_k / num_relevant_at_k
    return total_map / len(y_true)

import numpy as np

class Particle:
    def __init__(self, position, charge):
        self.position = position
        self.charge = charge

class SimulatedSystem:
    def __init__(self, particles, coulombs_constant):
        self.particles = particles
        self.coulombs_constant = coulombs_constant

    def calculatePotentialEnergy(self):
        total_energy = 0
        for i in range(len(self.particles)):
            for j in range(i+1, len(self.particles)):
                distance = abs(self.particles[i].position - self.particles[j].position)
                energy_contribution = (self.coulombs_constant * self.particles[i].charge * self.particles[j].charge) / distance
                total_energy += energy_contribution
        return total_energy

    def minimizeEnergy(self):
        learning_rate = 0.01
        max_iterations = 1000
        for _ in range(max_iterations):
            gradients = np.zeros(len(self.particles))
            for i in range(len(self.particles)):
                for j in range(len(self.particles)):
                    if i != j:
                        distance = abs(self.particles[i].position - self.particles[j].position)
                        force = (self.coulombs_constant * self.particles[i].charge * self.particles[j].charge) / distance**2
                        direction = np.sign(self.particles[i].position - self.particles[j].position)
                        gradients[i] += force * direction
            for i in range(len(self.particles)):
                self.particles[i].position -= learning_rate * gradients[i]

