def generate_pagination_html(current_page, total_pages, base_url):
    html = '<div class="pagination">'
    if current_page > 1:
        html += f'<a href="{base_url}?pagina=1">&laquo; First</a>'
        html += f'<a href="{base_url}?pagina={current_page - 1}">Previous</a>'
    else:
        html += '<span class="disabled">&laquo; First</span>'
        html += '<span class="disabled">Previous</span>'

    for page in range(1, total_pages + 1):
        if page == current_page:
            html += f'<span class="current">{page}</span>'
        else:
            html += f'<a href="{base_url}?pagina={page}">{page}</a>'

    if current_page < total_pages:
        html += f'<a href="{base_url}?pagina={current_page + 1}">Next</a>'
        html += f'<a href="{base_url}?pagina={total_pages}">Last &raquo;</a>'
    else:
        html += '<span class="disabled">Next</span>'
        html += '<span class="disabled">Last &raquo;</span>'

    html += '</div>'
    return html

function resolveModulePath(importPath, importingModulePath) {
  if (importPath.startsWith("./")) {
    const importSegments = importPath.split("/");
    const importingSegments = importingModulePath.split("/");
    importingSegments.pop(); // Remove the importing module's filename
    importSegments.shift(); // Remove the leading "./"
    return importingSegments.concat(importSegments).join("/");
  } else if (importPath.startsWith("../")) {
    const importSegments = importPath.split("/");
    const importingSegments = importingModulePath.split("/");
    importingSegments.pop(); // Remove the importing module's filename
    importSegments.shift(); // Remove the leading "../"
    while (importSegments[0] === "..") {
      importSegments.shift();
      importingSegments.pop();
    }
    return importingSegments.concat(importSegments).join("/");
  } else {
    return importPath;
  }
}

