import argparse
import pandas as pd
import numpy as np

def calculate_msd(trajectory):
    displacements = trajectory.diff().dropna()
    squared_displacements = (displacements[['x', 'y', 'z']] ** 2).sum(axis=1)
    msd = squared_displacements.groupby('time').mean()
    return msd

def main():
    parser = argparse.ArgumentParser(description='Calculate mean squared displacement (MSD) for particle diffusion')
    parser.add_argument('--file', type=str, help='Path to the trajectory file')
    args = parser.parse_args()

    if args.file:
        try:
            trajectory_data = pd.read_csv(args.file)
            msd_values = calculate_msd(trajectory_data)
            print(msd_values)
        except FileNotFoundError:
            print("Error: File not found")
    else:
        print("Error: Please provide the trajectory file using --file option")

if __name__ == "__main__":
