def workflow_order(tasks: List[Tuple[str, List[str]]]) -> List[str]:
    graph = {task: set(dependencies) for task, dependencies in tasks}
    result = []

    while graph:
        independent_tasks = [task for task, dependencies in graph.items() if not dependencies]
        if not independent_tasks:
            raise ValueError("Circular dependency detected")
        result.extend(independent_tasks)
        graph = {task: dependencies - set(independent_tasks) for task, dependencies in graph.items() if task not in independent_tasks}

    return result

