    def sequence_interpolant(self, formulas):
        from sympy import symbols, Eq, solve
        x = symbols('x')
        points = []
        for formula in formulas:
            y = eval(formula)
            points.append((x, y))
        interpolated_formula = 0
        for i in range(len(points)):
            term = 1
            for j in range(len(points)):
                if i != j:
