def is_balanced(s: str) -> bool:
    left_count = 0
    star_count = 0
    for char in s:
        if char == '(':
            left_count += 1
        elif char == ')':
            if left_count > 0:
                left_count -= 1
            elif star_count > 0:
                star_count -= 1
            else:
                return False
        elif char == '*':
            star_count += 1

    right_count = 0
    star_count = 0
    for char in s[::-1]:
        if char == ')':
            right_count += 1
        elif char == '*':
            star_count += 1
        else:
            break

    return left_count <= star_count + right_count

