def parse_setup_file(file_path: str) -> dict:
    with open(file_path, 'r') as file:
        content = file.read()

    setup_dict = {}
    try:
        parsed_content = ast.parse(content)
        for node in parsed_content.body:
            if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call) and node.value.func.id == 'setup':
                for keyword in node.value.keywords:
                    if keyword.arg == 'classifiers':
