def extract_file_extensions(resources: dict) -> list:
    file_extensions = set()
    for resource_type, resource_paths in resources.items():
        for resource_name, paths in resource_paths.items():
            for path in paths:
                file_extension = path.split('.')[-1]
                file_extensions.add(file_extension)
    return list(file_extensions)

