        self.dimension = dimension
        self.embedding_manifold = embedding_manifold

    def calculate_volume(self):
        if self.dimension == 1:
            return 0  # Volume of a 1-dimensional object is 0
        elif self.dimension == 2:
            return math.pi  # Volume of a 2-dimensional object (e.g., circle) is pi
        elif self.dimension == 3:
            return (4/3) * math.pi  # Volume of a 3-dimensional object (e.g., sphere) is (4/3) * pi
        else:
            return None  # Volume calculation not defined for dimensions higher than 3

    def calculate_surface_area(self):
        if self.dimension == 1:
            return 0  # Surface area of a 1-dimensional object is 0
        elif self.dimension == 2:
            return 2 * math.pi  # Surface area of a 2-dimensional object (e.g., circle) is 2 * pi
        elif self.dimension == 3:
            return 4 * math.pi  # Surface area of a 3-dimensional object (e.g., sphere) is 4 * pi
        else:
