        for i in range(len(self.grid)):
            for j in range(len(self.grid[0])):
                if self.grid[i][j] == 'P':
                    return (i, j)

    def move_up(self):
        x, y = self.player_position
        if x > 0 and self.grid[x - 1][y] != 'E':
            self.grid[x][y], self.grid[x - 1][y] = self.grid[x - 1][y], self.grid[x][y]
            self.player_position = (x - 1, y)

    def move_down(self):
        x, y = self.player_position
        if x < len(self.grid) - 1 and self.grid[x + 1][y] != 'E':
            self.grid[x][y], self.grid[x + 1][y] = self.grid[x + 1][y], self.grid[x][y]
            self.player_position = (x + 1, y)

    def move_left(self):
        x, y = self.player_position
        if y > 0 and self.grid[x][y - 1] != 'E':
            self.grid[x][y], self.grid[x][y - 1] = self.grid[x][y - 1], self.grid[x][y]
            self.player_position = (x, y - 1)

    def move_right(self):
        x, y = self.player_position
        if y < len(self.grid[0]) - 1 and self.grid[x][y + 1] != 'E':
            self.grid[x][y], self.grid[x][y + 1] = self.grid[x][y + 1], self.grid[x][y]
