def allocate_space(total_width, total_height, allocated_spaces):
    # Initialize a list to store the remaining free space in each row
    remaining_space = [Row(0, total_height, total_width)]

    # Iterate through the allocated spaces and update the remaining free space in each row
    for space in allocated_spaces:
        new_remaining_space = []
        for row in remaining_space:
            # Check if the allocated space overlaps with the current row
            if row.top < space.y + space.height and row.top + row.height > space.y:
                # Calculate the remaining free space in the row after allocating the space
                remaining_width = row.free_width - space.width
                if remaining_width > 0:
                    # If there is remaining free space, create two new rows representing the space before and after the allocated space
                    new_remaining_space.append(Row(row.top, space.y - row.top, row.free_width))
                    new_remaining_space.append(Row(space.y + space.height, row.top + row.height - space.y - space.height, row.free_width))
                else:
                    # If there is no remaining free space, create a new row with the remaining height and full width
                    new_remaining_space.append(Row(row.top, row.height, row.free_width))
            else:
                # If the allocated space does not overlap with the current row, keep the row as it is
                new_remaining_space.append(row)
        remaining_space = new_remaining_space

    return remaining_space

