import re

def extract_view_names(url_patterns):
    view_mapping = {}
    for pattern in url_patterns:
        match = re.search(r"name='(\w+)'", pattern)
        if match:
            view_name = match.group(1)
            url_path = re.search(r"path\('([^']+)'\)", pattern).group(1)
            if view_name in view_mapping:
                view_mapping[view_name].append(url_path)
            else:
                view_mapping[view_name] = [url_path]
    return view_mapping

