class HashMap:
    def __init__(self, size, default_value):
        self.size = size
        self.default_value = default_value
        self.map = {'lb': default_value}

    def _hash(self, key):
        return hash(key) % self.size

    def insert(self, key, value):
        index = self._hash(key)
        while self.map.get(index) is not None and self.map.get(index) != 'deleted':
            index = (index + 1) % self.size
        self.map[index] = (key, value)

    def retrieve(self, key):
        index = self._hash(key)
        while self.map.get(index) is not None:
            if self.map.get(index) == 'deleted' or self.map.get(index)[0] != key:
                index = (index + 1) % self.size
            else:
                return self.map.get(index)[1]
        return self.default_value

    def remove(self, key):
        index = self._hash(key)
        while self.map.get(index) is not None:
            if self.map.get(index) == 'deleted' or self.map.get(index)[0] != key:
                index = (index + 1) % self.size
            else:
                self.map[index] = 'deleted'
                return

import math

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

