import ripple from 'ripple-lib';

const port: string | number = process.env.PORT || 50051;
const wsURL: string = process.env.RippleAPIURL || 'wss://s.altnet.rippletest.net:51233';

type StartServerType = () => void;
export const startServer: StartServerType = (): void => {
  const rippleAPI = new ripple.RippleAPI({ server: wsURL });

  const sendPayment = (
    sourceAddress: string,
    destinationAddress: string,
    amount: string,
    issuer?: string,
    currency?: string
  ): Promise<any> => {
    return new Promise((resolve, reject) => {
      const payment = {
        source: {
          address: sourceAddress,
          maxAmount: {
            value: amount,
            currency: currency || 'XRP',
            issuer: issuer || ''
          }
        },
        destination: {
          address: destinationAddress,
          amount: {
            value: amount,
            currency: currency || 'XRP',
            issuer: issuer || ''
          }
        }
      };

      rippleAPI.connect().then(() => {
        return rippleAPI.preparePayment(sourceAddress, payment, { maxLedgerVersionOffset: 5 });
      }).then(prepared => {
        const { signedTransaction } = rippleAPI.sign(prepared.txJSON, 'yourSecretKey');
        return rippleAPI.submit(signedTransaction);
      }).then(result => {
        rippleAPI.disconnect();
        resolve(result);
      }).catch(error => {
        rippleAPI.disconnect();
        reject(error);
      });
    });
  };

  // Example usage
  sendPayment('sourceAddress', 'destinationAddress', '10', 'issuerAddress', 'USD')
    .then(transactionResult => {
      console.log('Payment transaction successful:', transactionResult);
    })
    .catch(error => {
      console.error('Payment transaction failed:', error);
    });
};

