```python
import random

class RandomApply:
    def __init__(self, augmentation, prob):
        self.augmentation = augmentation
        self.prob = prob

    def __call__(self, data, *args, **kwargs):
        if random.random() < self.prob:
            return self.augmentation(data, *args, **kwargs)
        else:
            return data

def apply_augmentation(images, augmentation_function, probability):
    random_caller = RandomApply(augmentation_function, probability)
    augmented_images = [random_caller(image) for image in images]
    return augmented_images
