    def move_left(self):
        new_col = self.player_position[1] - 1
        if 0 <= new_col < self.size and self.grid[self.player_position[0]][new_col] == self.step:
            self.player_position[1] = new_col

    def move_right(self):
        new_col = self.player_position[1] + 1
        if 0 <= new_col < self.size and self.grid[self.player_position[0]][new_col] == self.step:
            self.player_position[1] = new_col

