import numpy as np
import time

def optimize_and_save_to_csv(fitness_function, bounds, population_size, max_generations, mode, D):
    def generate_initial_population(bounds, population_size, D):
        population = np.zeros((population_size, D))
        for i in range(D):
            population[:, i] = np.random.uniform(bounds[i][0], bounds[i][1], size=population_size)
        return population

    def mutate(population, F, mode):
        if mode == "best/1/bin":
            idx = np.random.choice(population.shape[0], size=3, replace=False)
            return population[idx[0]] + F * (population[idx[1]] - population[idx[2]])
        # Add other mutation strategies as needed

    def crossover(target, mutant, CR):
        crossover_mask = np.random.rand(D) < CR
        trial = np.where(crossover_mask, mutant, target)
        return trial

    def optimize(fitness_function, bounds, population_size, max_generations, mode, D):
        population = generate_initial_population(bounds, population_size, D)
        best_fitness = np.inf
        best_position = None
        for generation in range(max_generations):
            for i in range(population_size):
                target = population[i]
                mutant = mutate(population, F=0.5, mode=mode)
                trial = crossover(target, mutant, CR=0.9)
                trial_fitness = fitness_function(trial)
                if trial_fitness < best_fitness:
                    best_fitness = trial_fitness
                    best_position = trial
            # Update population using selection strategy (e.g., replace worst)
        return best_fitness, best_position

    time1 = time.time()
    best_fitness_val, best_pos = optimize(fitness_function, bounds, population_size, max_generations, mode, D)
    time2 = time.time()
    print(time2 - time1)

    np.savetxt(f"DE_fitness_{mode}_{D}.csv", best_fitness_val, delimiter=",")
    np.savetxt(f"DE_bestpos_{mode}_{D}.csv", best_pos, delimiter=",")

