def move(position, direction, grid):
    x, y = position
    rows, cols = len(grid), len(grid[0])

    if direction == "up" and x > 0 and grid[x-1][y] != 1:
        return (x-1, y)
    elif direction == "down" and x < rows-1 and grid[x+1][y] != 1:
        return (x+1, y)
    elif direction == "left" and y > 0 and grid[x][y-1] != 1:
        return (x, y-1)
    elif direction == "right" and y < cols-1 and grid[x][y+1] != 1:
        return (x, y+1)
    else:
        return position

