class RuleEngine:
    def __init__(self):
        self.rules = []

    def add_rule(self, rule):
        """Adds a rule to the RuleEngine."""
        self.rules.append(rule)

    def match_rules(self, *tags):
        """Returns a list of actions for all rules that match any of the given tags."""
        matched_actions = []
        for rule in self.rules:
            if rule.matches(*tags):
                matched_actions.append(rule.action)
        return matched_actions


