def caesar_cipher(text, shift, mode):
    result = ""
    if mode == "encrypt":
        for char in text:
            if char.isalpha():
                shift_amount = (ord(char) - 65 + shift) % 26 + 65 if char.isupper() else (ord(char) - 97 + shift) % 26 + 97
                result += chr(shift_amount) if char.isalpha() else char
            else:
                result += char
    elif mode == "decrypt":
        shift = -shift  # In decryption, the shift is reversed
        for char in text:
            if char.isalpha():
                shift_amount = (ord(char) - 65 + shift) % 26 + 65 if char.isupper() else (ord(char) - 97 + shift) % 26 + 97
                result += chr(shift_amount) if char.isalpha() else char
            else:
                result += char
    return result

