        self.logged_messages = []

    def set_min_level(self, level):
        self.min_level = level

    def info(self, message):
        if self.min_level in ["INFO", "WARNING", "ERROR"]:
            self.logged_messages.append(("INFO", message))

    def error(self, message):
        if self.min_level in ["ERROR"]:
            self.logged_messages.append(("ERROR", message))

    def warning(self, message):
        if self.min_level in ["WARNING", "ERROR"]:
            self.logged_messages.append(("WARNING", message))

    def display_logs(self):
        for level, message in self.logged_messages:
            print(f"[{level}] {message}")

