from twisted.internet import reactor

class SessionManager:
    _expireCall = None

    def __init__(self, site, uid, reactor=None):
        """
        Initialize a session with a unique ID for that session.

        @param reactor: L{IReactorTime} used to schedule expiration of the
            session. If C{None}, the reactor associated with I{site} is used.
        """
        self.site = site
        self.uid = uid
        self.reactor = reactor if reactor else site.reactor

    def _expire_session(self):
        print(f"Session {self.uid} has expired")

    def schedule_session_expiration(self, time_interval):
        """
        Schedule the expiration of the session after the specified time interval.

        @param time_interval: Time interval in seconds after which the session should expire.
        """
        if self._expireCall:
            self._expireCall.cancel()  # Cancel any previously scheduled expiration

        self._expireCall = self.reactor.callLater(time_interval, self._expire_session)

