def cache_get_state_group_delta(cache: DictionaryCache) -> Callable:
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(prev_group, delta_ids):
            cache_key = (prev_group, delta_ids)
            if cache_key in cache:
