class MinMaxStack:
    def __init__(self):
        self.stack = []
        self.minMaxStack = []

    # O(1) time | O(1) space
    def push(self, value):
        if not self.minMaxStack:
            self.minMaxStack.append((value, value))
        else:
            currentMin, currentMax = self.minMaxStack[-1]
            self.minMaxStack.append((min(value, currentMin), max(value, currentMax))
        self.stack.append(value)

    # O(1) time | O(1) space
    def pop(self):
        if self.stack:
            self.minMaxStack.pop()
            return self.stack.pop()
        return None

    # O(1) time | O(1) space
    def getMin(self):
        if self.minMaxStack:
            return self.minMaxStack[-1][0]
        return None

