def diameter(graph, edge_distance):
    # Implement Warshall-Floyd algorithm to find the shortest path distances
    distance = [[float('inf') if i != j else 0 for j in range(len(graph))] for i in range(len(graph))]
    for i in range(len(graph)):
        for j in range(len(graph)):
            distance[i][j] = edge_distance(i, j)

    for k in range(len(graph)):
        for i in range(len(graph)):
            for j in range(len(graph)):
                distance[i][j] = min(distance[i][j], distance[i][k] + distance[k][j])

    # Find the diameter by finding the maximum shortest path distance
    diameter = 0
    for i in range(len(graph)):
        for j in range(len(graph)):
            diameter = max(diameter, distance[i][j])

    return diameter

