# Implementing the gen_prime() generator function
def gen_prime():
    num = 2
    primes = []
    while True:
        is_prime = True
        for prime in primes:
            if num % prime == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
            yield num
        num += 1

# Using the gen_prime() function to find the 10,001st prime number
