        self.before_middlewares.append(func)

    def register_after(self, func: Callable[[Request, Response], None]):
        self.after_middlewares.append(func)

    def execute(self, request: Request, response: Response) -> Response:
        for middleware_func in self.before_middlewares:
            middleware_func(request, response)

        # Main request handler logic goes here

        for middleware_func in self.after_middlewares:
            middleware_func(request, response)

        return response

