class IntegerIterator:
    def __init__(self, data: List[Union[int, str]]):
        self.integers = sorted([int(x) for x in data if isinstance(x, (int, str)) and str(x).isdigit()])

    def __iter__(self) -> 'IntegerIterator':
        self.index = 0
        return self

    def __next__(self) -> int:
        if self.index < len(self.integers):
            result = self.integers[self.index]
            self.index += 1
            return result
        else:
            raise StopIteration

