import numpy as np

class CustomNearestCentroid:
    def __init__(self, metric='euclidean'):
        self.metric = metric
        self.centroids = None

    def fit(self, X, y):
        unique_classes = np.unique(y)
        self.centroids = {}
        for cls in unique_classes:
            cls_points = X[y == cls]
            self.centroids[cls] = np.mean(cls_points, axis=0)

    def predict(self, X_test):
        if self.centroids is None:
            raise ValueError("Model not fitted yet. Call fit method first.")

        y_pred = []
        for point in X_test:
            min_dist = float('inf')
            closest_cls = None
            for cls, centroid in self.centroids.items():
                dist = np.linalg.norm(point - centroid) if self.metric == 'euclidean' else np.sum(np.abs(point - centroid))
                if dist < min_dist:
                    min_dist = dist
                    closest_cls = cls
            y_pred.append(closest_cls)
        return np.array(y_pred)

