class TableRobot(Robot):
    def executeinstruction(self, instruction, table):
        width, height = table
        if instruction == "MOVE":
            if self.facing == "NORTH" and self.y < height - 1:
                self.y += 1
            elif self.facing == "SOUTH" and self.y > 0:
                self.y -= 1
            elif self.facing == "EAST" and self.x < width - 1:
                self.x += 1
            elif self.facing == "WEST" and self.x > 0:
                self.x -= 1
        elif instruction == "LEFT":
            if self.facing == "NORTH":
                self.facing = "WEST"
            elif self.facing == "SOUTH":
                self.facing = "EAST"
            elif self.facing == "EAST":
                self.facing = "NORTH"
            elif self.facing == "WEST":
                self.facing = "SOUTH"
        elif instruction == "RIGHT":
            if self.facing == "NORTH":
                self.facing = "EAST"
            elif self.facing == "SOUTH":
                self.facing = "WEST"
            elif self.facing == "EAST":
                self.facing = "SOUTH"
            elif self.facing == "WEST":
                self.facing = "NORTH"
        elif instruction == "REPORT":
            print(f"Robot's current position: ({self.x}, {self.y}), facing {self.facing}")

