class Version:
    def __init__(self, version_str):
        parts = version_str.split('-')
        version_numbers = parts[0].split('.')
        self.major = int(version_numbers[0])
        self.minor = int(version_numbers[1])
        self.patch = int(version_numbers[2])
        self.pre_release = parts[1] if len(parts) > 1 else None

    def __lt__(self, other):
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch
        return self.pre_release < other.pre_release if self.pre_release and other.pre_release else False

    def __eq__(self, other):
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch and self.pre_release == other.pre_release

    def is_prerelease(self):
        return self.pre_release is not None

