class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = dict()

    def add_node(self, node):
        self.nodes.add(node)

    def add_edge(self, node1, node2):
        if node1 in self.edges:
            self.edges[node1].append(node2)
        else:
            self.edges[node1] = [node2]

        if node2 in self.edges:
            self.edges[node2].append(node1)
        else:
            self.edges[node2] = [node1]

    def dfs(self, start_node):
        visited = []
        stack = [start_node]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.append(node)
                if node in self.edges:
                    stack.extend([n for n in self.edges[node] if n not in visited])
        return visited

    def bfs(self, start_node):
        visited = []
        queue = [start_node]
        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.append(node)
                if node in self.edges:
                    queue.extend([n for n in self.edges[node] if n not in visited])
        return visited

