def findClosingTagPosition(html, element):
    stack = []
    start_tag = '<' + element
    end_tag = '</' + element + '>'
    for i in range(len(html)):
        if html[i:i+len(start_tag)] == start_tag:
            stack.append(i)
        elif html[i:i+len(end_tag)] == end_tag:
            if stack:
