from typing import List

def count_occurrences(a: List[int], x: int) -> int:
    def binary_search_left(arr, target):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    def binary_search_right(arr, target):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid
        return left

    left_index = binary_search_left(a, x)
    right_index = binary_search_right(a, x)
    return right_index - left_index

