class CustomTextFormatter:
    def __init__(self):
        self.mappings = {}

    def add_mapping(self, key, value):
        self.mappings[key] = value

    def replace_placeholders(self, text):
        for key, value in self.mappings.items():
            placeholder = "{" + key + "}"
            text = text.replace(placeholder, value)
        return text

    def format_text(self, text):
        formatted_text = text
        while True:
            replaced_text = self.replace_placeholders(formatted_text)
            if replaced_text == formatted_text:
                break
            formatted_text = replaced_text
        if "{" in formatted_text or "}" in formatted_text:
            raise KeyError("Unmapped placeholder found")
        return formatted_text

