class SummaryProcessor:
    def __init__(self, pd):
        self.pd = pd

    def item_count(self, cluster_versions):
        unique_versions = set(cluster_versions)
        return len(unique_versions)

    def format_columns(self, section):
        formatted_rows = []
        for item in section:
            formatted_rows.append(' | '.join(str(x) for x in item))
        return formatted_rows

    def build_summary_info(self):
        summary = []
        sum_pd = ['PD', '%s' % len(self.pd.hosts),
                  self.item_count([item['config']['cluster-version']
