class FileSystem:
    def __init__(self, name):
        self.root = {'name': name, 'contents': {}, 'parent': None}
        self.current_directory = self.root

    def create_file(self, path, content):
        directories, file_name = path.rsplit('/', 1)
        current = self.root
        for directory in directories.split('/')[1:]:
            current = current['contents'][directory]
        current['contents'][file_name] = {'name': file_name, 'content': content, 'parent': current}

    def create_directory(self, path):
        directories, directory_name = path.rsplit('/', 1)
        current = self.root
        for directory in directories.split('/')[1:]:
            current = current['contents'][directory]
        current['contents'][directory_name] = {'name': directory_name, 'contents': {}, 'parent': current}

    def get_contents(self, path):
        current = self.root
        if path != '/':
            for directory in path.split('/')[1:]:
                current = current['contents'][directory]
        if 'content' in current:
            return current['content']
        else:
            return list(current['contents'].keys())

    def navigate(self, path):
        current = self.root
        if path != '/':
            for directory in path.split('/')[1:]:
                current = current['contents'][directory]
        self.current_directory = current

    def get_current_directory(self):
        return self.current_directory['name']

