def simulate_robot_movement(commands: str, search_limit: int) -> Union[Tuple[int, int], bool]:
    x, y = 0, 0
    distance = 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
        distance += 1
        if search_limit is not None and distance >= search_limit:
            return False
    return (x, y)

