class AugStyle(object):
    def __init__(self, probability):
        self.probability = probability

    def apply_augmentation(self, image, augmentation_function, *args):
        if np.random.rand() < self.probability:
            return augmentation_function(image, *args)
        else:
            return image

    def rotate(self, image, angle):
        return self.apply_augmentation(image, lambda img, a: img.rotate(a), angle)

    def flip(self, image, horizontal):
        if horizontal:
            return self.apply_augmentation(image, lambda img: img.transpose(Image.FLIP_LEFT_RIGHT))
        else:
            return self.apply_augmentation(image, lambda img: img.transpose(Image.FLIP_TOP_BOTTOM))

    def scale(self, image, factor):
        width, height = image.size
        new_size = (int(width * factor), int(height * factor))
        return self.apply_augmentation(image, lambda img, size: img.resize(size, Image.ANTIALIAS), new_size)

    def color_manipulation(self, image, brightness_factor, contrast_factor):
        enhancer = ImageEnhance.Brightness(image)
        image = enhancer.enhance(brightness_factor)
        enhancer = ImageEnhance.Contrast(image)
        image = enhancer.enhance(contrast_factor)
