from bisect import bisect_left

def clean_monochromator_data(data: List[Tuple[float, float]]) -> List[Tuple[float, float]]:
    cleaned_data = []
    visible_light_min = 380.0
    visible_light_max = 750.0

    # Remove negative intensity values and wavelengths outside the visible light spectrum
    for wavelength, intensity in data:
        if intensity >= 0 and visible_light_min <= wavelength <= visible_light_max:
            cleaned_data.append((wavelength, intensity))

    # Interpolate missing intensity values within the visible light spectrum
    interpolated_data = []
    wavelengths = [d[0] for d in cleaned_data]
    intensities = [d[1] for d in cleaned_data]

    for wavelength in range(int(visible_light_min), int(visible_light_max) + 1):
        if wavelength in wavelengths:
            interpolated_data.append((wavelength, intensities[wavelengths.index(wavelength)]))
        else:
            idx = bisect_left(wavelengths, wavelength)
            if idx == 0:
                interpolated_data.append((wavelength, intensities[0]))
            elif idx == len(wavelengths):
                interpolated_data.append((wavelength, intensities[-1]))
            else:
                x0, x1 = wavelengths[idx - 1], wavelengths[idx]
                y0, y1 = intensities[idx - 1], intensities[idx]
                interpolated_intensity = y0 + (y1 - y0) * (wavelength - x0) / (x1 - x0)
                interpolated_data.append((wavelength, interpolated_intensity))

    return interpolated_data

