class PIDController:
    def __init__(self, kp, ki, kd):
        self.kp = kp
        self.ki = ki
        self.kd = kd
        self.i_term = 0
        self.prev_error = 0

    @property
    def kp(self):
        return self._kp

    @kp.setter
    def kp(self, kp):
        """Set the proportional gain."""
        self._kp = kp

    @property
    def ki(self):
        return self._ki

    @ki.setter
    def ki(self, ki):
        """Set the integral gain."""
        self._ki = ki

    @property
    def kd(self):
        return self._kd

    @kd.setter
    def kd(self, kd):
        """Set the derivative gain."""
        self._kd = kd

    def calculate(self, sp, pv):
        error = sp - pv
        p_term = self.kp * error
        self.i_term += self.ki * error
        d_term = self.kd * (error - self.prev_error)
        output = p_term + self.i_term + d_term
        self.prev_error = error
        return output

