class CryptoConfigParser(ConfigParser):

    def __init__(self, *args, **kwargs): 
        key = kwargs.pop('crypt_key', None)
        if key is not None:
            self.crypt_key = key
        else:
            self.crypt_key = None
        ConfigParser.__init__(self, *args, **kwargs)

    def get(self, section, option, *args, **kwargs):
        raw_val = ConfigParser.get(self, section, option, *args, **kwargs)
        if self.crypt_key is not None and raw_val.startswith('ENCRYPTED:'):
            encrypted_data = base64.b64decode(raw_val[len('ENCRYPTED:'):])
            salt = encrypted_data[:16]
            ciphertext = encrypted_data[16:]
            key = PBKDF2(self.crypt_key, salt, dkLen=32)
            cipher = AES.new(key, AES.MODE_GCM, nonce=ciphertext[:16])
            decrypted_val = cipher.decrypt_and_verify(ciphertext[16:], ciphertext[16:])
            return decrypted_val.decode('utf-8')
        else:
            return raw_val

