    def __init__(self):
        self.cache = {}

    def read(self, cache_key):
        """Read content from the cache."""
        return self.cache.get(cache_key)

    def key_from_url(self, url, params=None):
        if params is None:
            return url
        else:
            sorted_params = sorted(params.items())
            key_parts = [f"{key}={value}" for key, value in sorted_params]
            return f"{url}?{'&'.join(key_parts)}"

