def sort_sentiment(output: AnalyzerOutput) -> np.ndarray:
    sorted_sentiments = np.sort(output.sentiment_values)
    return sorted_sentiments

def list_to_arr(result: Union[List[AnalyzerOutput], AnalyzerOutput]) -> np.ndarray:
    if isinstance(result, list):
        return np.vstack([sort_sentiment(out) for out in result])
    else:
        return sort_sentiment(result)

def format_output(result: Union[List[AnalyzerOutput], AnalyzerOutput]) -> np.ndarray:
    try:
        return sort_sentiment(result)
    except AttributeError:
        return list_to_arr(result)

