def simulate_environment(grid, agent_position, target_position):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = [(agent_position, [agent_position])]

    while queue:
        current, path = queue.pop(0)
        if current == target_position:
            return path

        if current in visited:
            continue
        visited.add(current)

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_r, new_c = current[0] + dr, current[1] + dc
            if 0 <= new_r < rows and 0 <= new_c < cols and grid[new_r][new_c] == 0:
                queue.append(((new_r, new_c), path + [(new_r, new_c)]))

    return []

class Quantity:
    def __init__(self, value, unit):
        self.value = value
        self.unit = unit

    def parse(self, s):
        value, unit = s.split()
        return Quantity(float(value), unit)

    def convert_to(self, new_unit):
        # Define conversion factors for different units
        conversion_factors = {
            "mL": 1,
            "L": 1000,
            "g": 1,
            "kg": 1000
        }
        # Convert the quantity to the new unit
        if self.unit in conversion_factors and new_unit in conversion_factors:
            converted_value = self.value * conversion_factors[self.unit] / conversion_factors[new_unit]
            return Quantity(converted_value, new_unit)
        else:
            raise ValueError("Invalid units for conversion")

    def __add__(self, other):
        if self.unit == other.unit:
            return Quantity(self.value + other.value, self.unit)
        else:
            raise ValueError("Units must be the same for addition")

    def __sub__(self, other):
        if self.unit == other.unit:
            return Quantity(self.value - other.value, self.unit)
        else:
            raise ValueError("Units must be the same for subtraction")

