import React, { useState, useEffect } from 'react';

const App = () => {
  const [items, setItems] = useState([]);
  const [newItem, setNewItem] = useState('');

  useEffect(() => {
    // Fetch items from API and update the state using setItems
    fetch('https://api.example.com/items')
      .then(response => response.json())
      .then(data => setItems(data))
      .catch(error => console.error('Error fetching items:', error));
  }, []);

  const handleAddItem = () => {
    if (newItem.trim() !== '') {
      // Add the new item to the list and update the state
      setItems([...items, newItem]);
      setNewItem('');
    }
  };

  const handleDeleteItem = (itemId) => {
    // Delete the item with the given itemId from the list and update the state
    const updatedItems = items.filter((item, index) => index !== itemId);
    setItems(updatedItems);
  };

  return (
    <div>
      <h1>Item List</h1>
      <ul>
        {items.map((item, index) => (
          <li key={index}>
            {item}
            <button onClick={() => handleDeleteItem(index)}>Delete</button>
          </li>
        ))}
      </ul>
      <input type="text" value={newItem} onChange={(e) => setNewItem(e.target.value)} />
      <button onClick={handleAddItem}>Add Item</button>
    </div>
  );
};

export default App;

