    parser.read(config_file)

    if section in parser:
        if option in parser[section]:
            value = parser[section][option]
            if value.isdigit():
                return int(value)
            elif value.replace('.', '', 1).isdigit():
                return float(value)
            elif value.lower() == 'true' or value.lower() == 'false':
                return value.lower() == 'true'
