class BankingSystem:
    def __init__(self):
        self.accounts = {}  # Dictionary to store account details

    def create_account(self, name, initial_deposit):
        account_number = len(self.accounts) + 1  # Generate unique account number
        self.accounts[account_number] = {'name': name, 'balance': initial_deposit}
        return account_number

    def deposit(self, account_number, amount):
        if account_number in self.accounts:
            self.accounts[account_number]['balance'] += amount
        else:
            raise ValueError("Invalid account number")

    def withdraw(self, account_number, amount):
        if account_number in self.accounts:
            if self.accounts[account_number]['balance'] >= amount:
                self.accounts[account_number]['balance'] -= amount
            else:
                raise ValueError("Insufficient funds")
        else:
            raise ValueError("Invalid account number")

    def balance_inquiry(self, account_number):
        if account_number in self.accounts:
            return self.accounts[account_number]['balance']
        else:
            raise ValueError("Invalid account number")

