class BinaryTree:
    def __init__(self):
        self.root = None
        self.nodes_dict = {}

    def _calculate_real_height(self, node):
        if node is None:
            return 0
        else:
            left_height = self._calculate_real_height(node.left)
            right_height = self._calculate_real_height(node.right)
            return max(left_height, right_height) + 1

    def populate_nodes_dict(self, node=None, height=0):
        if node is None:
            node = self.root
        if node:
            self.nodes_dict[node, height] = [node.left, node.right]
            self.populate_nodes_dict(node.left, height + 1)
            self.populate_nodes_dict(node.right, height + 1)

