class MigrationOperation:
    def __init__(self, name):
        self.name = name

def resolve_migration_order(dependencies, operations):
    # Create a dictionary to store the dependencies for each migration
    dependency_map = {}
    for dependency in dependencies:
        parent, child = dependency
        if child not in dependency_map:
            dependency_map[child] = set()
        dependency_map[child].add(parent)

    # Perform a topological sort to determine the order of migrations
    visited = set()
    order = []

    def dfs(migration):
        if migration in visited:
            return
        visited.add(migration)
        if migration in dependency_map:
            for dependency in dependency_map[migration]:
                dfs(dependency)
        order.append(migration)

    for operation in operations:
        dfs(operation.name)

    return order[::-1]

