def FindClosest(endpoints: List[T], reference: TripEndpoint) -> T:
    closest = None
    min_distance = float('inf')
    for endpoint in endpoints:
        distance = ((endpoint.latitude - reference.latitude) ** 2 +
                    (endpoint.longitude - reference.longitude) ** 2) ** 0.5
        if distance < min_distance:
            min_distance = distance
