from qiskit import QuantumCircuit, execute
from qiskit.providers.aer import AerSimulator

def simulate_quantum_circuit(quantum_circuit, n_shots, memory=False, seed=None, noise_model=None):
    qiskit_circuit = QuantumCircuit(len(quantum_circuit), len(quantum_circuit[0]['measurement']))

    for gate in quantum_circuit:
        if 'gate' in gate:
            if gate['gate'] == 'H':
                qiskit_circuit.h(gate['target'])
            elif gate['gate'] == 'CX':
                qiskit_circuit.cx(gate['control'], gate['target'])
        elif 'measurement' in gate:
            qiskit_circuit.measure(gate['measurement'], gate['measurement'])

    backend = AerSimulator()
    job = execute(qiskit_circuit, backend, shots=n_shots, memory=memory, seed_simulator=seed, noise_model=noise_model)
    return job.job_id()

