import sys

def calculate_coverage(intervals_file, reads_file, output_file):
    intervals = read_bed_file(intervals_file)
    reads = read_bed_file(reads_file)

    coverage_info = []
    for interval in intervals:
        depth, breadth = calculate_interval_coverage(interval, reads)
        coverage_info.append((interval, depth, breadth))

    write_coverage_info(output_file, coverage_info)

def read_bed_file(file_path):
    with open(file_path, 'r') as file:
        return [line.strip().split('\t') for line in file]

def calculate_interval_coverage(interval, reads):
    interval_start, interval_end = map(int, interval[1:3])
    overlapping_reads = [read for read in reads if int(read[1]) < interval_end and int(read[2]) > interval_start]

    depth = sum(len(read) for read in overlapping_reads) / len(interval)
    breadth = sum(int(read[2]) - int(read[1]) for read in overlapping_reads) / (interval_end - interval_start)

    return depth, breadth

def write_coverage_info(output_file, coverage_info):
    with open(output_file, 'w') as file:
        for interval, depth, breadth in coverage_info:
            file.write(f"{interval}\t{depth}\t{breadth}\n")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python coverage_simulator.py <intervals_file> <reads_file> <output_file>")
