def parse_html_styles(html_code):
    styles_dict = {}
    soup = BeautifulSoup(html_code, 'html.parser')
    elements = soup.find_all(id=True)
    for element in elements:
        style = element.get('style')
        if style:
            styles = style.split(';')
            style_properties = {}
            for prop in styles:
                if ':' in prop:
                    key, value = prop.split(':')
                    style_properties[key.strip()] = value.strip()
            styles_dict[element['id']] = style_properties
    return styles_dict

