def similar_products(model, products, n=5):
    recommendations = {}
    for product in products:
        if product in model:
            similar = model.most_similar(positive=[product], topn=n)
            recommendations[product] = [sim[0] for sim in similar]
        else:
            recommendations[product] = []  # Product not found in the model

