def check_generic_type(file_path: str) -> List[Tuple[int, str]]:
    errors = []
    with open(file_path, 'r') as file:
        tree = ast.parse(file.read(), filename=file_path)

    for node in ast.walk(tree):
        if isinstance(node, ast.AnnAssign) and isinstance(node.annotation, ast.Subscript):
            errors.append((node.lineno, "Assignment to generic type is not allowed"))
        elif isinstance(node, ast.Delete) and isinstance(node.targets[0], ast.Name) and isinstance(node.targets[0].ctx, ast.Del) and isinstance(node.targets[0].ctx, ast.Subscript):
            errors.append((node.lineno, "Deletion of generic type is not allowed"))

    return errors

