import random

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Miller-Rabin primality test
    def miller_rabin_test(d, n):
        a = 2 + random.randint(1, n - 4)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return True
        while d != n - 1:
            x = (x * x) % n
            d *= 2
            if x == 1:
                return False
            if x == n - 1:
                return True
        return False

    # Find d such that n-1 = 2^r * d
    d = n - 1
    while d % 2 == 0:
        d //= 2

    # Number of iterations for accuracy
    iterations = 5

    # Perform the Miller-Rabin test for accuracy
    for _ in range(iterations):
        if not miller_rabin_test(d, n):
            return False

    return True

