class Binheap:
    def __init__(self):
        self.container = [(0, 0)]  # Initialize with a dummy element at index 0

    def push(self, element):
        self.container.append(element)
        self._perc_up(len(self.container) - 1)

    def pop(self):
        if len(self.container) > 2:
            self._swap(1, len(self.container) - 1)
            to_return = self.container.pop()
            self._perc_down(1)
        elif len(self.container) == 2:
            to_return = self.container.pop()
        else:
            to_return = None
        return to_return

    def _perc_up(self, i):
        while i // 2 > 0:
            if self.container[i][0] < self.container[i // 2][0]:
                self._swap(i, i // 2)
            i = i // 2

    def _perc_down(self, i):
        while (i * 2) <= len(self.container) - 1:
            mc = self._min_child(i)
            if self.container[i][0] > self.container[mc][0]:
                self._swap(i, mc)
            i = mc

    def _min_child(self, i):
        if i * 2 + 1 > len(self.container) - 1:
            return i * 2
        else:
            if self.container[i * 2][0] < self.container[i * 2 + 1][0]:
                return i * 2
            else:
                return i * 2 + 1

    def _swap(self, i, j):
        self.container[i], self.container[j] = self.container[j], self.container[i]


class PriorityQueue:
    def __init__(self):
        """Initialize priority queue with a binary heap."""
        self._container = Binheap()

    def insert(self, val, priority=0):
        """Insert a val into the queue with an argument for the priority."""
        self._container.push((priority, val))

    def pop(self):
        """Remove the most important item from the queue."""
        to_return = self._container.container[1][1]
        if not to_return:
            return None
        else:
            return self._container.pop()

