def pre_order_traversal(root):
    result = []
    if root:
        result.append(root.value)  # Visit the current node
        result += pre_order_traversal(root.left)  # Traverse the left subtree
        result += pre_order_traversal(root.right)  # Traverse the right subtree
    return result

