import tensorflow as tf

class CustomRegularizedAdamOptimizer(tf.compat.v1.train.AdamOptimizer):
    def __init__(self, learning_rate=0.001, beta1=0.9, beta2=0.999, epsilon=1e-8, reg_lambda=0.01):
        super(CustomRegularizedAdamOptimizer, self).__init__(learning_rate=learning_rate, beta1=beta1, beta2=beta2, epsilon=epsilon)
        self.reg_lambda = reg_lambda

    def apply_gradients(self, grads_and_vars, global_step=None, name=None):
        var_list = [v for g, v in grads_and_vars]
        with tf.control_dependencies(None):
            self._create_slots(var_list)
        update_ops = []
        with tf.control_dependencies(update_ops):
            for grad, var in grads_and_vars:
                if grad is None or var is None:
                    continue
                if isinstance(grad, tf.IndexedSlices):
                    grad_values = grad.values
                else:
                    grad_values = grad
                if self.reg_lambda > 0:
                    grad_values += self.reg_lambda * var
                m = self.get_slot(var, "m")
                v = self.get_slot(var, "v")
                beta1_power, beta2_power = self._get_beta_accumulators()
                lr_t = (tf.cast(self._lr_t, var.dtype.base_dtype) * tf.sqrt(1 - beta2_power) / (1 - beta1_power))
                m_t = m.assign(beta1 * m + (1 - beta1) * grad)
                v_t = v.assign(beta2 * v + (1 - beta2) * tf.square(grad))
                var_update = var.assign_sub(lr_t * m_t / (tf.sqrt(v_t) + self.epsilon))
                update_ops.extend([m_t, v_t, var_update])
        return tf.group(*update_ops, name=name)

