def decode_image(layers):
    res = []
    for r in zip(*layers):
        layer = []
        for p in zip(*r):
            layer.append([x for x in p if x != "2"][0])
        res.append(layer)

    decoded_image = []
    for l in res:
        decoded_image.append("".join(l).replace("0", " ").replace("1", "█"))

