def list_file_paths(file_system):
    def dfs(curr_path, curr_node, result):
        if isinstance(curr_node, str):  # Base case: file
            result.append(curr_path)
        else:  # Recursive case: directory
            for key, value in curr_node.items():
                if curr_path:
                    new_path = f"{curr_path}/{key}"
                else:
                    new_path = key
                dfs(new_path, value, result)

    file_paths = []
    dfs('', file_system, file_paths)
    return sorted(file_paths)

