def isBalanced(s: str) -> bool:
    stack = []
    opening = set(["(", "[", "{"])
    closing = set([")", "]", "}"])
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in closing:
            if not stack or stack.pop() != mapping[char]:
                return False

    return not stack

