def calculate_distance(vertex1, vertex2):
    x1, y1, z1 = map(float, vertex1.split()[2:])
    x2, y2, z2 = map(float, vertex2.split()[2:])
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2 + (z2 - z1) ** 2)

