def count_html_tags(html_snippet):
    tag_counts = {}
    current_tag = ""
    in_tag = False

    for char in html_snippet:
        if char == "<":
            in_tag = True
            current_tag = ""
        elif char == ">":
            in_tag = False
            if current_tag.startswith("/"):
                tag_name = current_tag[1:]
                if tag_name in tag_counts:
                    tag_counts[tag_name] += 1
                else:
                    tag_counts[tag_name] = 1
            else:
                tag_name = current_tag.split(" ")[0]
                if tag_name in tag_counts:
                    tag_counts[tag_name] += 1
                else:
                    tag_counts[tag_name] = 1
        elif in_tag:
            current_tag += char

    return tag_counts

